mapper.select:
SELECT id, sync_run_id, dataset, source, source_time, business_date, fetch_batch_id, data_version, checksum, record_key, quality_status, reason_code, raw_summary, detected_at, issue_status FROM fund_data_quality_issue WHERE 1 = 1
AND sync_run_id = #{bo.syncRunId}
AND dataset = #{bo.dataset}
AND fetch_batch_id = #{bo.fetchBatchId}
AND reason_code = #{bo.reasonCode}
AND issue_status = #{bo.issueStatus}
AND detected_at >= #{bo.detectedAtStart}
AND detected_at <= #{bo.detectedAtEnd}
ORDER BY detected_at DESC, id DESC
